def decide(observation, memory):
    """Use safety gating, confidence confirmation, and hysteretic target steering."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    previous = memory.get("action", "")
    scan = memory.get("scan", "SCAN_LEFT")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    risk = float(observation["closing_risk"])
    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    def finish(action, confidence, next_state):
        memory["action"] = action
        memory["state"] = next_state
        memory["last_bearing"] = round(bearing, 2)
        return action, confidence, memory

    if safety < 0.60 or risk >= 0.75:
        return finish("STOP", 0.99, "STOPPED")

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60
    if not confirmed:
        if lost <= 1 and state in {"VERIFY", "LOCKED", "APPROACH", "REACQUIRE"}:
            return finish("STOP", 0.92, "REACQUIRE")
        action = scan
        memory["scan"] = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
        return finish(action, 0.74, "SEARCH")

    if track_age < 2:
        return finish("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        heading = abs(float(observation["heading_error"]))
        if heading <= 12.0 and identity_conf >= 0.80 and target_conf >= 0.70:
            return finish("ARRIVED", 0.96, "ARRIVED")
        turn = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        if abs(bearing) < 5.0:
            turn = "VEER_LEFT" if float(observation["heading_error"]) < 0 else "VEER_RIGHT"
        if (turn == "VEER_LEFT" and not left) or (turn == "VEER_RIGHT" and not right):
            return finish("STOP", 0.94, "STOPPED")
        return finish(turn, 0.88, "APPROACH")

    if abs(bearing) >= 10.0:
        turn = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        if (turn == "VEER_LEFT" and left) or (turn == "VEER_RIGHT" and right):
            return finish(turn, 0.90, "APPROACH")
        if center:
            return finish("FORWARD", 0.82, "APPROACH")
        return finish("STOP", 0.95, "STOPPED")

    if previous in {"VEER_LEFT", "VEER_RIGHT"} and abs(bearing) >= 6.0:
        if (previous == "VEER_LEFT" and left) or (previous == "VEER_RIGHT" and right):
            return finish(previous, 0.84, "APPROACH")
    if center:
        return finish("FORWARD", 0.90, "APPROACH")
    if bearing < 0 and left:
        return finish("VEER_LEFT", 0.82, "APPROACH")
    if bearing > 0 and right:
        return finish("VEER_RIGHT", 0.82, "APPROACH")
    if left:
        return finish("VEER_LEFT", 0.76, "APPROACH")
    if right:
        return finish("VEER_RIGHT", 0.76, "APPROACH")
    return finish("STOP", 0.98, "STOPPED")
